/** Real native equipment, combat, conversion and two-tick dropped-stack fixtures. */
public final class SlabDropChecks {
    private SlabDropChecks() { }
    private static State running,stopping;
    private static String stopEpoch;
    private static ItemEntity stopToken;
    private static List<Zombie> stopActors=List.of();
    private static void require(boolean ok,String text){if(!ok)throw new IllegalStateException("Slab drops: "+text);}
    private static net.minecraft.nbt.CompoundTag saved(Entity e,ServerLevel level){var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,level.registryAccess());e.saveWithoutId(out);return out.buildResult();}
    private static ItemEntity token(ServerLevel level,Vec3 at,int count,LivingEntity author,LbcSlabDropItem.Kind kind){var t=new ItemEntity(level,at.x,at.y,at.z,new ItemStack(kind.item(),count));if(author!=null)t.setThrower(author);t.setNoGravity(true);t.setDeltaMovement(Vec3.ZERO);t.setPickUpDelay(1000);require(level.addFreshEntity(t),"native token admission");return t;}
    private static final class State implements AutoCloseable {
        final GameController game;final ServerLevel level;final ServerPlayer alpha,beta;final GameChecks.WandThirdPlayerState alphaState,betaState;
        final Vec3 origin;final Set<Entity> existing=Collections.newSetFromMap(new IdentityHashMap<>());final Set<Zombie> mine=Collections.newSetFromMap(new IdentityHashMap<>());final Set<Long> forced=new HashSet<>();final List<ItemEntity> tokens=new ArrayList<>();
        final int alphaKills,betaKills;final boolean mobDrops;ItemEntity stack,paused,unloaded;final Map<Zombie,Vec3> frozen=new IdentityHashMap<>();int phase,lastTick,wait;
        State(GameController game){this.game=game;level=game.maps().level();alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));beta=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));require(game.playing() && alpha!=null && beta!=null && game.allowDamage(beta),"actual match participants");alphaState=new GameChecks.WandThirdPlayerState(alpha,game.items().mana());betaState=new GameChecks.WandThirdPlayerState(beta,game.items().mana());origin=new Vec3(Math.floor(alpha.getX()/16)*16+8.37,270.7,Math.floor(alpha.getZ()/16)*16+8.81);level.getAllEntities().forEach(existing::add);alphaKills=kills(alpha);betaKills=kills(beta);mobDrops=level.getGameRules().get(GameRules.MOB_DROPS);}
        int kills(ServerPlayer p){return p.getStats().getValue(net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS));}
        void initialize(){var p=BlockPos.containing(origin);long key=net.minecraft.world.level.ChunkPos.pack(p.getX()>>4,p.getZ()>>4);if(!level.getForceLoadedChunks().contains(key)){forced.add(key);level.setChunkForced(p.getX()>>4,p.getZ()>>4,true);}level.getChunkAt(p);
            for(var player:List.of(alpha,beta)){player.closeContainer();player.getInventory().clearContent();player.removeAllEffects();player.setGameMode(GameType.SURVIVAL);player.setNoGravity(true);player.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);player.setHealth(1000);player.setAbsorptionAmount(0);player.setInvulnerableTime(0);player.damageCooldownTime=0;}
            alpha.teleportTo(level,origin.x+20,origin.y,origin.z,Set.of(),0,0,true);beta.teleportTo(level,origin.x+22,origin.y,origin.z,Set.of(),0,0,true);level.getGameRules().set(GameRules.MOB_DROPS,true,game.server());lastTick=game.server().getTickCount();}
        void capture(){for(var z:game.items().slabDrops().snapshot())if(!existing.contains(z) && !z.isRemoved())mine.add(z);}
        void clear(){capture();new ArrayList<>(mine).forEach(Entity::discard);mine.clear();}
        ItemEntity drop(LbcSlabDropItem.Kind kind,int count){var t=token(level,origin,count,alpha,kind);tokens.add(t);return t;}
        Zombie batch(LbcSlabDropItem.Kind kind){clear();var t=drop(kind,2);t.setTarget(beta.getUUID());t.setYRot(37);t.setXRot(23);require(game.items().slabDrops().ready(t,kind),"loaded native admission");require(game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"shared one debit");require(!game.items().specialDrops().spawn(t) && t.getItem().getCount()==1,"same tick guard");t.discard();capture();require(mine.size()==1,"one native zombie");return mine.iterator().next();}
        void presentation(){for(var kind:LbcSlabDropItem.Kind.values()){var s=new ItemStack(kind.item());var data=s.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();require(data.size()==2 && data.getIntOr(kind.flag(),0)==1 && data.getIntOr("drop",0)==1,"exact source flags "+kind);
                if(kind==LbcSlabDropItem.Kind.NORMAL)require(Identifier.parse("lbc:drop_boss").equals(s.get(DataComponents.ITEM_MODEL)) && Identifier.parse("lbc:tier_ff").equals(s.get(DataComponents.TOOLTIP_STYLE)) && s.getHoverName().getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents label && label.getKey().equals("trap_slab"),"normal source presentation");
                else require(Identifier.parse("minecraft:barrier").equals(s.get(DataComponents.ITEM_MODEL)) && !s.has(DataComponents.CUSTOM_NAME) && !s.has(DataComponents.TOOLTIP_STYLE),"legacy plain token");var loot=game.lbc().rollTable(level,origin,alpha,kind==LbcSlabDropItem.Kind.NORMAL?"lbc:ported/slab_drop":"lbc:ported/slab_drop_old");require(loot.size()==1 && ItemStack.isSameItemSameComponents(s,loot.getFirst()),"public leaf prototype "+kind);}
            for(var v:List.of(Items.BARRIER,Items.REPEATING_COMMAND_BLOCK,Items.PAPER))require(!LbcSlabDropItem.matches(new ItemStack(v)),"unflagged lookalike rejected");}
        void weapon(ItemStack reward,LbcSlabDropItem.Kind kind){require(reward.is(Items.OAK_SLAB) && reward.getCount()==1,"one actual oak slab");var label=reward.get(DataComponents.CUSTOM_NAME);require(label!=null && !label.getStyle().isItalic(),"nonitalic native reward name");if(kind==LbcSlabDropItem.Kind.NORMAL)require(label.getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents tr && tr.getKey().equals("agressive_slab") && Identifier.parse("lbc:tier_d").equals(reward.get(DataComponents.TOOLTIP_STYLE)),"normal translated tier_d reward");else require(label.getString().equals("Агрессивный полублок") && !reward.has(DataComponents.TOOLTIP_STYLE),"legacy literal reward");
            var modifiers=reward.get(DataComponents.ATTRIBUTE_MODIFIERS);require(modifiers!=null && modifiers.modifiers().size()==1,"native modifier list codec retained");var entry=modifiers.modifiers().getFirst();require(entry.attribute().equals(Attributes.ATTACK_DAMAGE) && entry.slot()==EquipmentSlotGroup.MAINHAND && entry.modifier().id().equals(Identifier.parse("minecraft:base_attack_damage")) && entry.modifier().amount()==(kind==LbcSlabDropItem.Kind.NORMAL?6:3) && entry.modifier().operation()==net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADD_VALUE,"source +6/+3 native mainhand modifier");}
        void defaults(Zombie zombie,LbcSlabDropItem.Kind kind){var tag=saved(zombie,level);require(zombie.getClass()==Zombie.class && zombie.isBaby() && !zombie.isNoAi() && !zombie.isNoGravity() && zombie.getTarget()==null && zombie.getHealth()==20 && zombie.getMaxHealth()==20,"native baby/health/AI defaults");require(zombie.position().distanceTo(origin)<1e-8 && zombie.getYRot()==0 && zombie.getXRot()==0 && zombie.getDeltaMovement().equals(Vec3.ZERO),"fractional token origin and summon defaults");require(zombie.isPersistenceRequired()==(kind==LbcSlabDropItem.Kind.NORMAL) && tag.getStringOr("DeathLootTable","").equals("minecraft:empty"),"source persistence difference and empty normal loot");var effect=zombie.getEffect(net.minecraft.world.effect.MobEffects.INVISIBILITY);require(effect!=null && effect.getDuration()==2000000 && effect.getAmplifier()==1 && !effect.isVisible(),"source long invisible amplifier1/no particles");weapon(zombie.getItemBySlot(EquipmentSlot.HEAD),kind);require(zombie.getDropChances().byEquipment(EquipmentSlot.HEAD)==(kind==LbcSlabDropItem.Kind.NORMAL?2:1) && zombie.getMainHandItem().isEmpty() && zombie.getAttributeValue(Attributes.ATTACK_DAMAGE)==3,"guaranteed head slot, no invented attack boost while worn");require(game.items().slabDrops().owner(zombie)==zombie && game.items().currentEpoch(zombie),"actual thrower independent from pickup target");}
        Cow cow(){var c=new Cow(EntityTypes.COW,level);c.setPos(origin.add(0,4,0));c.setNoAi(true);c.setNoGravity(true);require(level.addFreshEntity(c),"native disposable victim");return c;}
        void combat(Zombie actor){actor.setNoAi(true);actor.setNoGravity(true);var cow=cow();try{cow.setHealth(1);int before=kills(alpha);require(actor.doHurtTarget(level,cow) && cow.isDeadOrDying() && cow.getKillCredit()==actor && kills(alpha)==before,"native melee credits the slab Mob without player kill reward");}finally{game.items().indirectKills().clear(cow);cow.discard();}
            for(boolean newer:List.of(false,true)){var target=cow();try{require(actor.doHurtTarget(level,target),"native nonlethal hit");if(newer){target.setInvulnerableTime(0);target.damageCooldownTime=0;target.hurtServer(level,target.damageSources().playerAttack(beta),1);}target.setHealth(1);target.setInvulnerableTime(0);target.damageCooldownTime=0;target.hurtServer(level,target.damageSources().fellOutOfWorld(),1000);require(target.isDeadOrDying() && target.getKillCredit()==(newer?beta:actor),"melee void provenance/newer attacker");}finally{game.items().indirectKills().clear(target);target.discard();}}
            for(String tag:List.of("spectator","rcdenyalways","sauvojen_tuntija","strict_map_object","magic_academy","transformator")){var npc=cow();npc.entityTags().add(tag);try{require(!actor.doHurtTarget(level,npc) && npc.getHealth()==npc.getMaxHealth(),"native role guard "+tag);actor.setTarget(npc);require(actor.getTarget()!=npc,"native setTarget role guard "+tag);}finally{npc.discard();}}
            var board=game.server().getScoreboard();var oldAlpha=alpha.getTeam();var oldBeta=beta.getTeam();require(board.getPlayerTeam("codex_slab_probe")==null,"fixture team available");var team=board.addPlayerTeam("codex_slab_probe");team.setAllowFriendlyFire(false);try{board.addPlayerToTeam(alpha.getScoreboardName(),team);board.addPlayerToTeam(beta.getScoreboardName(),team);beta.setInvulnerableTime(0);beta.damageCooldownTime=0;require(actor.doHurtTarget(level,beta) && beta.getHealth()<1000,"unowned slab hits allied player");actor.setTarget(beta);require(actor.getTarget()==beta,"unowned slab targets allied player");alpha.setInvulnerableTime(0);alpha.damageCooldownTime=0;require(actor.doHurtTarget(level,alpha) && alpha.getHealth()<1000,"native thrower retaliation remains");}finally{board.removePlayerTeam(team);if(oldAlpha!=null)board.addPlayerToTeam(alpha.getScoreboardName(),oldAlpha);if(oldBeta!=null)board.addPlayerToTeam(beta.getScoreboardName(),oldBeta);actor.setTarget(null);alpha.setHealth(1000);alpha.setRemainingFireTicks(0);}
        }
        ItemStack death(Zombie actor,LbcSlabDropItem.Kind kind){var before=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());level.getAllEntities().forEach(before::add);int prior=kills(beta);require(actor.hurtServer(level,actor.damageSources().playerAttack(beta),1000) && actor.isDeadOrDying() && actor.getKillCredit()==beta && kills(beta)==prior+1,"native killer death/statistic");var items=new ArrayList<ItemEntity>();for(var e:level.getAllEntities())if(!before.contains(e) && e instanceof ItemEntity i)items.add(i);require(items.size()==1,"empty native death table plus exactly one guaranteed equipment drop");var reward=items.getFirst().getItem().copy();weapon(reward,kind);items.forEach(Entity::discard);actor.discard();return reward;}
        void fallReward(){
            var actor=batch(LbcSlabDropItem.Kind.NORMAL);var before=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());level.getAllEntities().forEach(before::add);
            require(actor.getKillCredit()==null&&actor.hurtServer(level,actor.damageSources().fall(),1000)&&actor.isDeadOrDying(),"actual fall death without a player attacker");
            var rewards=new ArrayList<ItemEntity>();for(var entity:level.getAllEntities())if(!before.contains(entity)&&entity instanceof ItemEntity item)rewards.add(item);
            require(rewards.size()==1,"environmental death drops exactly one preserved slab");weapon(rewards.getFirst().getItem(),LbcSlabDropItem.Kind.NORMAL);rewards.forEach(Entity::discard);actor.discard();
        }
        void equipment(){fallReward();for(var kind:LbcSlabDropItem.Kind.values()){var actor=batch(kind);defaults(actor,kind);var slab=death(actor,kind);actor=batch(kind);actor.setNoAi(true);actor.setNoGravity(true);actor.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);actor.setItemSlot(EquipmentSlot.MAINHAND,slab);actor.tick();require(actor.getAttributeValue(Attributes.ATTACK_DAMAGE)==3+(kind==LbcSlabDropItem.Kind.NORMAL?6:3),"native equipment tick applies dropped slab hand modifier");var target=cow();try{float before=target.getHealth();require(actor.doHurtTarget(level,target) && Math.abs(before-target.getHealth()-(kind==LbcSlabDropItem.Kind.NORMAL?9:6))<1e-5,"actual slab-equipped native melee damage");}finally{target.discard();}}}
        void conversion(){for(var kind:LbcSlabDropItem.Kind.values()){var source=batch(kind);var helmet=source.getItemBySlot(EquipmentSlot.HEAD).copy();var drowned=source.convertTo(EntityTypes.DROWNED,ConversionParams.single(source,true,true),converted->{});require(drowned!=null && source.isRemoved() && LbcSlabDrops.managed(drowned) && game.items().slabDrops().owner(drowned)==drowned && game.items().currentEpoch(drowned),"native Drowned conversion cause/epoch");capture();require(drowned.isBaby() && drowned.hasEffect(net.minecraft.world.effect.MobEffects.INVISIBILITY) && ItemStack.isSameItemSameComponents(helmet,drowned.getItemBySlot(EquipmentSlot.HEAD)) && drowned.getDropChances().byEquipment(EquipmentSlot.HEAD)==(kind==LbcSlabDropItem.Kind.NORMAL?2:1),"native conversion preserves baby/effect/equipment/chance");require(!saved(drowned,level).getStringOr("DeathLootTable","").equals("minecraft:empty"),"conversion retains native Drowned loot rather than invented empty-loot lineage");combat(drowned);}}
        void guards(){var stale=drop(LbcSlabDropItem.Kind.NORMAL,2);stale.entityTags().add("skywars2.items.stale-fixture");require(!game.items().specialDrops().spawn(stale) && stale.getItem().getCount()==2,"stale no debit");stale.discard();var fake=drop(LbcSlabDropItem.Kind.NORMAL,2);fake.makeFakeItem();require(!game.items().specialDrops().spawn(fake),"native give visual rejected");fake.discard();var remote=drop(LbcSlabDropItem.Kind.NORMAL,2);int x=(BlockPos.containing(origin).getX()>>4)+128,z=(BlockPos.containing(origin).getZ()>>4)+128;while(level.getChunkSource().getChunkNow(x,z)!=null)x+=128;remote.setPos(x*16+8,origin.y,z*16+8);require(!game.items().specialDrops().spawn(remote) && remote.getItem().getCount()==2 && level.getChunkSource().getChunkNow(x,z)==null,"unresident no loads or debit");remote.discard();}
        boolean step(){require(game.playing(),"actual match retained");int now=game.server().getTickCount();if(now==lastTick)return false;lastTick=now;switch(phase){
            case 0->{presentation();guards();equipment();combat(batch(LbcSlabDropItem.Kind.NORMAL));conversion();clear();var both=drop(LbcSlabDropItem.Kind.NORMAL,2);var flags=both.getItem().getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();flags.putInt("slab_old",1);both.getItem().set(DataComponents.CUSTOM_DATA,CustomData.of(flags));require(game.items().specialDrops().spawn(both) && both.getItem().getCount()==1,"both source flags one debit");capture();require(mine.size()==2 && mine.stream().filter(Zombie::isPersistenceRequired).count()==1,"independent normal/old source payloads");var normal=mine.stream().filter(Zombie::isPersistenceRequired).findFirst().orElseThrow();var old=mine.stream().filter(z->!z.isPersistenceRequired()).findFirst().orElseThrow();require(normal.getId()<old.getId(),"normal summon precedes old summon in actual native source order");both.discard();clear();stack=drop(LbcSlabDropItem.Kind.NORMAL,2);phase++;}
            case 1->{capture();require(stack.getItem().getCount()==1 && mine.size()==1,"actual first tick dispatch");phase++;}
            case 2->{capture();require(stack.isRemoved() && mine.size()==2,"actual second tick debit");for(var z:mine)frozen.put(z,z.position());game.items().timeStop().begin(level,200);paused=drop(LbcSlabDropItem.Kind.OLD,2);phase++;}
            case 3->{require(paused.getItem().getCount()==2 && frozen.entrySet().stream().allMatch(e->!e.getKey().isRemoved() && e.getKey().position().distanceTo(e.getValue())<1e-8),"time stop freezes actors and debit");if(++wait>=3){paused.discard();game.items().timeStop().end(level);clear();unloaded=drop(LbcSlabDropItem.Kind.NORMAL,2);game.items().specialDrops().unloaded(unloaded);phase++;}}
            case 4->{require(!unloaded.isRemoved() && unloaded.getItem().getCount()==2,"unloaded token cannot replay");unloaded.discard();var z=batch(LbcSlabDropItem.Kind.NORMAL);game.items().slabDrops().unloaded(z);require(!game.items().slabDrops().snapshot().contains(z),"unload detaches");game.items().slabDrops().loaded(z);require(game.items().slabDrops().owner(z)==z && game.items().slabDrops().snapshot().contains(z),"same epoch load restores cause");z.entityTags().removeIf(t->t.startsWith("skywars2.items."));z.entityTags().add("skywars2.items.stale-fixture");game.items().slabDrops().unloaded(z);game.items().slabDrops().loaded(z);require(z.isRemoved(),"stale actor quiet rejection");return true;}
            default->throw new IllegalStateException("Unknown slab phase "+phase);
        }return false;}
        public void close(){close(false);}
        void close(boolean keepActors){game.items().timeStop().end(level);tokens.forEach(Entity::discard);if(!keepActors)clear();var leftovers=new ArrayList<Entity>();for(var e:level.getAllEntities())if(!existing.contains(e) && !(e instanceof ServerPlayer) && !(keepActors && LbcSlabDrops.managed(e)) && Math.abs(e.getX()-origin.x)<8 && Math.abs(e.getZ()-origin.z)<8)leftovers.add(e);leftovers.forEach(Entity::discard);for(long key:forced)level.setChunkForced(net.minecraft.world.level.ChunkPos.getX(key),net.minecraft.world.level.ChunkPos.getZ(key),false);level.getGameRules().set(GameRules.MOB_DROPS,mobDrops,game.server());alphaState.restore(game);betaState.restore(game);alpha.getStats().setValue(alpha,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),alphaKills);beta.getStats().setValue(beta,net.minecraft.stats.Stats.CUSTOM.get(net.minecraft.stats.Stats.MOB_KILLS),betaKills);}
    }
    private static void failure(State state,Throwable error){try{state.close();}catch(Throwable cleanup){if(error!=cleanup)error.addSuppressed(cleanup);}finally{running=null;stopping=null;}}
    public static void run(GameController game){require(running==null && stopping==null,"already running");running=new State(game);try{running.initialize();}catch(RuntimeException|Error error){failure(running,error);throw error;}}
    public static void tick(GameController game){if(stopping!=null){var s=stopping;if(game.server().getTickCount()==s.lastTick)return;try{game.items().timeStop().end(s.level);var normal=s.batch(LbcSlabDropItem.Kind.NORMAL);var old=s.drop(LbcSlabDropItem.Kind.OLD,1);require(game.items().slabDrops().spawn(old,LbcSlabDropItem.Kind.OLD),"old stop actor");old.discard();s.capture();stopActors=List.copyOf(s.mine);require(stopActors.size()==2,"real pair before stop");for(var z:stopActors){z.setNoAi(true);z.setNoGravity(true);}stopEpoch=game.items().epoch();s.close(true);game.items().timeStop().begin(s.level,200);stopToken=token(s.level,s.origin.add(0,4,0),3,s.alpha,LbcSlabDropItem.Kind.NORMAL);require(!game.items().specialDrops().spawn(stopToken) && stopToken.getItem().getCount()==3,"pending token stop pause");stopping=null;SkyWars2.LOGGER.info("[check] PASS slab-drops-stop-probe");}catch(Throwable error){failure(s,error);SkyWars2.LOGGER.error("[check] FAIL slab-drops-stop-probe",error);}return;}if(running==null)return;var s=running;try{if(s.step()){s.close();running=null;SkyWars2.LOGGER.info("[check] PASS slab-drops");}}catch(Throwable error){failure(s,error);SkyWars2.LOGGER.error("[check] FAIL slab-drops",error);}}
    public static void stopProbe(GameController game){require(game.playing() && running==null && stopping==null,"actual stop probe");stopping=new State(game);try{stopping.initialize();}catch(RuntimeException|Error error){failure(stopping,error);throw error;}}
    public static void cleanup(GameController game){require(!game.items().currentEpoch(stopEpoch) && stopToken!=null && stopToken.getItem().getCount()==3 && game.items().slabDrops().trackedCount()==0 && stopActors.size()==2 && stopActors.stream().allMatch(Entity::isRemoved),"actual match stop quiet actor/pending cleanup");require(!game.items().specialDrops().spawn(stopToken),"stopped token no replay");stopToken.discard();stopToken=null;stopEpoch=null;stopActors=List.of();SkyWars2.LOGGER.info("[check] PASS slab-drops-cleanup");}
}
